// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { Boxes, IndianRupee, PackageCheck, TriangleAlert } from 'lucide-react';
import { useEffect, useState } from 'react';
import Loading from '../../components/common/Loading';
import RevenueChart from '../../components/vendor/RevenueChart';
import StatCard from '../../components/vendor/StatCard';
import { getErrorMessage, vendorAPI } from '../../services/api';
export default function Dashboard() {
 const [data,setData]=useState(null);const[loading,setLoading]=useState(true);const[error,setError]=useState('');
 useEffect(()=>{vendorAPI.getDashboard().then((r)=>setData(r.data.data)).catch((e)=>setError(getErrorMessage(e))).finally(()=>setLoading(false));},[]);
 if(loading)return <Loading label="Loading vendor dashboard…"/>; if(error)return <div className="rounded-xl bg-red-50 p-4 text-red-700">{error}</div>;
 return <div><div><h1 className="page-title">Vendor Dashboard</h1><p className="mt-1 text-sm text-slate-500">Live operational snapshot of your Vendora storefront.</p></div><div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><div className="sm:col-span-2"><StatCard label="Total Revenue" value={`₹${Number(data.total_revenue).toLocaleString('en-IN')}`} trend={`₹${Number(data.revenue_this_month).toLocaleString('en-IN')} this month`} icon={IndianRupee} variant="featured"/></div><StatCard label="Products" value={data.total_products} icon={Boxes}/><StatCard label="Active Orders" value={data.active_orders} icon={PackageCheck}/><StatCard label="Low Stock" value={data.low_stock_count} icon={TriangleAlert} trend={data.low_stock_count?'Needs attention':'Stock healthy'} trendPositive={!data.low_stock_count}/></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.6fr_1fr]"><RevenueChart data={data.monthly_revenue}/><div className="panel p-5"><h3 className="font-bold">Low stock products</h3><div className="mt-4 space-y-3">{data.low_stock_products.length?data.low_stock_products.map((p)=><div key={p.product_id} className="flex items-center justify-between rounded-xl bg-red-50/60 px-3 py-2"><div><p className="text-sm font-semibold">{p.name}</p><p className="text-xs text-slate-400">₹{Number(p.price).toLocaleString('en-IN')}</p></div><span className="rounded-full bg-red-100 px-2 py-1 text-xs font-bold text-red-700">{p.stock_qty} left</span></div>):<p className="text-sm text-slate-500">No low-stock products.</p>}</div></div></div><div className="panel mt-6 overflow-hidden"><div className="border-b border-slate-100 p-5"><h3 className="font-bold">Recent orders</h3></div><div className="divide-y divide-slate-100">{data.recent_orders.map((o)=><div key={o.order_id} className="flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-semibold">Order #{o.order_id} · {o.customer_name}</p><p className="text-xs text-slate-400">{o.item_count} item(s) · {new Date(o.created_at).toLocaleString()}</p></div><div className="text-right"><p className="font-mono font-bold">₹{Number(o.vendor_total).toLocaleString('en-IN')}</p><p className="text-xs font-semibold capitalize text-violet-600">{o.status}</p></div></div>)}</div></div></div>;
}
